bool Init(CreateTextureFn create_texture, const char* fonts_dir, const char* media_dir)
{
    bool ok = true;
    (void)media_dir;
    F_Inter_Bold = detail_LoadFont(0, fonts_dir);
    if (!F_Inter_Bold) { F_Inter_Bold = ImGui::GetIO().Fonts->AddFontDefault(); ok = false; }
    F_Inter_Regular = detail_LoadFont(1, fonts_dir);
    if (!F_Inter_Regular) { F_Inter_Regular = ImGui::GetIO().Fonts->AddFontDefault(); ok = false; }
    F_Inter_SemiBold = detail_LoadFont(2, fonts_dir);
    if (!F_Inter_SemiBold) { F_Inter_SemiBold = ImGui::GetIO().Fonts->AddFontDefault(); ok = false; }
    F_Inter_Medium = detail_LoadFont(3, fonts_dir);
    if (!F_Inter_Medium) { F_Inter_Medium = ImGui::GetIO().Fonts->AddFontDefault(); ok = false; }
    T_Icon_aim_mask = create_texture ? detail_LoadTexture(0, create_texture) : 0;
    T_Icon_eye_mask = create_texture ? detail_LoadTexture(1, create_texture) : 0;
    T_Icon_misc_mask = create_texture ? detail_LoadTexture(2, create_texture) : 0;
    T_Icon_gear_mask = create_texture ? detail_LoadTexture(3, create_texture) : 0;
    return ok;
}

